package com.dormrepair.file.controller;import com.dormrepair.common.enums.FileBizTypeEnum;import com.dormrepair.common.result.Result;import com.dormrepair.file.service.FileService;import com.dormrepair.file.vo.FileUploadResponse;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/files") public class FileController {private final FileService service;public FileController(FileService s){service=s;}@PostMapping("/upload")public Result<FileUploadResponse> upload(@RequestParam MultipartFile file,@RequestParam String bizType){return Result.success(service.upload(file,FileBizTypeEnum.fromCode(bizType)));}@DeleteMapping("/{id}")public Result<Void> delete(@PathVariable Long id){service.deleteUnusedFile(id);return Result.success();}}
